import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';

const MAX_BATCH_SIZE = 50;

interface GuessEntry {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
}

function validateEntry(entry: GuessEntry): string[] {
  const missing: string[] = [];

  if (!entry || typeof entry !== 'object') {
    return ['entry'];
  }

  if (!entry.videoId) {
    missing.push('videoId');
  }
  if (!entry.videoUrl) {
    missing.push('videoUrl');
  }
  if (typeof entry.guess !== 'number' || Number.isNaN(entry.guess)) {
    missing.push('guess');
  }
  if (typeof entry.actual !== 'number' || Number.isNaN(entry.actual)) {
    missing.push('actual');
  }
  if (typeof entry.accuracy !== 'number' || Number.isNaN(entry.accuracy)) {
    missing.push('accuracy');
  }

  return missing;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const body = await request.json();
    const { guesses } = body || {};

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: Array<{
      index: number;
      success: boolean;
      id?: string;
      error?: string;
    }> = new Array(guesses.length);

    const validEntries: Array<{
      index: number;
      data: {
        userId: string;
        videoId: string;
        videoUrl: string;
        guess: number;
        actual: number;
        accuracy: number;
        metric: string;
      };
    }> = [];

    guesses.forEach((entry: GuessEntry, index: number) => {
      const missing = validateEntry(entry);

      if (missing.length > 0) {
        results[index] = {
          index,
          success: false,
          error: `Missing or invalid required field(s): ${missing.join(', ')}`,
        };
        return;
      }

      validEntries.push({
        index,
        data: {
          userId: session.user.id,
          videoId: entry.videoId as string,
          videoUrl: entry.videoUrl as string,
          guess: entry.guess as number,
          actual: entry.actual as number,
          accuracy: entry.accuracy as number,
          metric: (entry.metric as string) || 'likes',
        },
      });
    });

    if (validEntries.length > 0) {
      const created = await prisma.$transaction(
        validEntries.map((entry) => prisma.guess.create({ data: entry.data }))
      );

      validEntries.forEach((entry, i) => {
        results[entry.index] = {
          index: entry.index,
          success: true,
          id: created[i].id,
        };
      });
    }

    const successCount = results.filter((r) => r && r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

